SELECT t0.id AS "Id",t0.source AS "Source",t0.applicant_first_name AS "Applicant FirstName",t0.applicant_nick_name AS "Applicant NickName" FROM (SELECT t1.id AS "id",'agency1' AS "source",t1.first_name AS "applicant_first_name",t1.nick_name AS "applicant_nick_name",t1.home AS "applicant_home",t1.firm_name AS "firm_legal_name",'agency_one' AS "_set" FROM org.applications_a AS t1 UNION ALL SELECT t2.id AS "id",'agency2' AS "source",t2.given_name AS "applicant_first_name",t2.known_as AS "applicant_nick_name",t2.address AS "applicant_home",'vogue' AS "firm_legal_name",'agency_two' AS "_set" FROM org.applications_b AS t2) AS t0 ORDER BY t0.id ASC NULLS FIRST, t0.source ASC NULLS FIRST
